// Generated byte fixtures; no external datasets required.
// The byte convenience API can retry native errors through GDAL. The unit tests exercise
// the native decoder even with GDAL enabled; range and stream checks run in both builds.
#![cfg(feature = "flatgeobuf")]
use flatbuffers::FlatBufferBuilder;
use flatgeobuf::{Feature as FgbFeature, FeatureArgs, Geometry as FgbGeometry, GeometryArgs, GeometryType as FgbType, Header, HeaderArgs};
use terrio::{Layer, Result};
#[path = "common/flatgeobuf.rs"]
mod fixtures;
use fixtures::fixture;
fn parse(bytes: &[u8]) -> Result<Layer> {
    terrio::memory::open_vector_bytes(bytes.to_vec(), "fixture.fgb", &Default::default()).map(|mut d| d.layers.remove(0))
}
fn accepted_by_native_readers(bytes: &[u8]) -> bool {
    let file = terrio::sparse::SparseFile::new(bytes.len() as u64);
    file.insert(0, bytes);
    let range = terrio::vector::read_flatgeobuf_sparse(&file, "fixture.fgb", None).is_ok();
    #[cfg(not(feature = "gdal"))]
    assert_eq!(parse(bytes).is_ok(), range);
    let mut file = tempfile::Builder::new().suffix(".fgb").tempfile().unwrap();
    std::io::Write::write_all(&mut file, bytes).unwrap();
    let stream = terrio::stream::open_layers(file.path().to_str().unwrap(), &Default::default(), 1);
    let stream_ok = stream.and_then(|streams| streams.into_iter().map(|s| s.read_all()).collect::<Result<Vec<_>>>()).is_ok();
    assert_eq!(range, stream_ok);
    range
}

#[test]
fn truncation_and_counts() {
    assert!(accepted_by_native_readers(&fixture(0, false, &[])));
    assert!(!accepted_by_native_readers(&fixture(1, false, &[])));
    for count in [0, 1] {
        for n in 1..4 {
            let mut bytes = fixture(count, false, &[]);
            bytes.extend_from_slice(&[16, 0, 0][..n]);
            assert!(!accepted_by_native_readers(&bytes));
        }
    }
    let bytes = fixture(1, true, &[7.0]);
    assert!(accepted_by_native_readers(&bytes));
    assert!(!accepted_by_native_readers(&bytes[..bytes.len() - 1]));
    assert!(!accepted_by_native_readers(&fixture(2, true, &[7.0])));
    let mut bytes = fixture(1, false, &[]);
    bytes.extend_from_slice(&u32::MAX.to_le_bytes());
    assert!(!accepted_by_native_readers(&bytes));
}

#[test]
fn measures_are_preserved_and_dimensions_checked() {
    let layer = parse(&fixture(1, true, &[7.0])).unwrap();
    assert_eq!(layer.features[0].geometry.as_ref().unwrap().all_coords()[0].m, Some(7.0));
    // Extra values, and dimensions the header does not declare, are ignored, as GDAL ignores them.
    assert!(accepted_by_native_readers(&fixture(1, true, &[7.0, 8.0])));
    assert!(accepted_by_native_readers(&fixture(1, false, &[7.0])));
    assert_eq!(parse(&fixture(1, false, &[7.0])).unwrap().features[0].geometry.as_ref().unwrap().all_coords()[0].m, None);
    let mut bytes = fixture(1, true, &[]);
    let mut b = FlatBufferBuilder::new();
    let xy = b.create_vector(&[1.0, 2.0, 3.0, 4.0]);
    let m = b.create_vector(&[7.0]);
    let g = FgbGeometry::create(&mut b, &GeometryArgs { xy: Some(xy), m: Some(m), ..Default::default() });
    let f = FgbFeature::create(&mut b, &FeatureArgs { geometry: Some(g), ..Default::default() });
    b.finish_size_prefixed(f, None);
    bytes.extend_from_slice(b.finished_data());
    assert!(!accepted_by_native_readers(&bytes));
}

#[test]
fn declared_z_must_be_present() {
    let mut b = FlatBufferBuilder::new();
    let h = Header::create(
        &mut b,
        &HeaderArgs { features_count: 1, index_node_size: 0, has_z: true, geometry_type: FgbType::Point, ..Default::default() },
    );
    b.finish_size_prefixed(h, None);
    let mut bytes = b"fgb\x03fgb\x00".to_vec();
    bytes.extend_from_slice(b.finished_data());
    let mut b = FlatBufferBuilder::new();
    let xy = b.create_vector(&[1.0, 2.0]);
    let g = FgbGeometry::create(&mut b, &GeometryArgs { xy: Some(xy), ..Default::default() });
    let f = FgbFeature::create(&mut b, &FeatureArgs { geometry: Some(g), ..Default::default() });
    b.finish_size_prefixed(f, None);
    bytes.extend_from_slice(b.finished_data());
    assert!(!accepted_by_native_readers(&bytes));
}

/// A polygon or multiline with explicit ends, optionally nested in a collection.
fn part_ends_fixture(kind: FgbType, ends: &[u32], nested: bool) -> Vec<u8> {
    let mut b = FlatBufferBuilder::new();
    let h = Header::create(
        &mut b,
        &HeaderArgs {
            features_count: 1,
            index_node_size: 0,
            geometry_type: if nested { FgbType::GeometryCollection } else { kind },
            ..Default::default()
        },
    );
    b.finish_size_prefixed(h, None);
    let mut bytes = b"fgb\x03fgb\x00".to_vec();
    bytes.extend_from_slice(b.finished_data());
    let mut b = FlatBufferBuilder::new();
    let xy = b.create_vector(&[0.0, 0.0, 0.0, 1.0, 1.0, 1.0, 1.0, 0.0]);
    let ends = b.create_vector(ends);
    let mut geometry = FgbGeometry::create(&mut b, &GeometryArgs { xy: Some(xy), ends: Some(ends), type_: kind, ..Default::default() });
    if nested {
        let parts = b.create_vector(&[geometry]);
        geometry =
            FgbGeometry::create(&mut b, &GeometryArgs { parts: Some(parts), type_: FgbType::GeometryCollection, ..Default::default() });
    }
    let f = FgbFeature::create(&mut b, &FeatureArgs { geometry: Some(geometry), ..Default::default() });
    b.finish_size_prefixed(f, None);
    bytes.extend_from_slice(b.finished_data());
    bytes
}

#[test]
fn part_ends_are_checked_before_splitting() {
    for kind in [FgbType::Polygon, FgbType::MultiLineString] {
        for nested in [false, true] {
            for ends in [&[4, 2][..], &[2, 5][..], &[u32::MAX][..]] {
                assert!(!accepted_by_native_readers(&part_ends_fixture(kind, ends, nested)));
            }
            for ends in [&[4][..], &[2, 4][..], &[0, 4][..], &[4, 4][..], &[2, 3][..]] {
                assert!(accepted_by_native_readers(&part_ends_fixture(kind, ends, nested)));
            }
        }
    }
}
